// Üretilen dosya: tool/ozgun/uret.py. Araştırma Yöntemleri · Anket ve ölçek tasarımı: soru yazım hataları, çift namlulu ve yönlendirici sorular, sosyal beğenilirlik, tavan-taban etkisi ve güvenirlik (kolay).
const ozResearch16Kolay = <(String, String, List<String>, String)>[
  ('Stevens tarafından geliştirilen dörtlü ölçme sınıflamasında, yalnızca nesneleri birbirinden ayırmaya yarayan ve büyüklük ilişkisi taşımayan düzey hangisidir?', 'Sınıflama ölçeği', ['Sıralama ölçeği', 'Eşit aralıklı ölçek', 'Eşit oranlı ölçek'], 'Sınıflama (nominal) düzeyinde sayılar veya semboller yalnızca kategorileri adlandırmak amacıyla kullanılır; aralarında nicel büyüklük farkı yoktur.'),
  ('Futbolcuların sırtlarındaki forma numaralarının istatistiksel açıdan aritmetik ortalamasının alınamamasının temel ölçme gerekçesi nedir?', 'Rakamların yalnızca kimlik etiketi görevi üstlenmesi', ['Sporcuların sahadaki koşu mesafelerinin değişkenlik göstermesi', 'Numaraların başlangıç noktasının mutlak yokluğu ifade etmesi', 'Takım kadrosundaki oyuncu sayısının çift sayıdan oluşması'], 'Forma numaraları nominal (sınıflama) düzeyindedir; sayısal görünmelerine karşın miktar belirtmezler, bu yüzden toplama veya ortalama işlemi anlamsızdır.'),
  ('Askerî rütbelerin er, onbaşı, çavuş ve teğmen biçiminde dizilmesi hangi ölçme düzeyinin tipik bir örneğini oluşturur?', 'Sıralama düzeyi', ['Sınıflama düzeyi', 'Eşit oranlı düzey', 'Eşit aralıklı düzey'], 'Rütbeler arasında hiyerarşik bir ast-üst ilişkisi vardır ancak rütbeler arasındaki yetki farklarının sayısal olarak eşit olduğu söylenemez.'),
  ('Hanehalkı aylık net gelirini Türk lirası cinsinden doğrudan yazdıran bir anket maddesi hangi ölçme düzeyinde veri üretir?', 'Eşit oranlı ölçek', ['Eşit aralıklı ölçek', 'Sıralama ölçeği', 'Adlandırma ölçeği'], 'Gelirin sıfır olması parasal kazancın tam yokluğunu gösterir ve 40 bin TL gelir, 20 bin TL gelirin tam iki katıdır; dolayısıyla oranlı ölçmedir.'),
  ('Nominal düzeyde toplanmış \'doğum yeri ili\' değişkeni için hesaplanabilecek en uygun merkezi eğilim ölçüsü hangisidir?', 'Tepe değer (mod)', ['Aritmetik ortalama', 'Ortanca (medyan)', 'Harmonik ortalama'], 'Sınıflama ölçeğinde sıralama veya toplama yapılamadığından yalnızca en sık tekrar eden kategori olan mod (tepe değer) bulunabilir.'),
  ('Katılımcıların kendi cümleleriyle özgürce yanıt verdiği açık uçlu anket maddelerinin araştırmacıya sağladığı en önemli üstünlük nedir?', 'Önceden öngörülemeyen özgün görüşleri ortaya çıkarması', ['Veri girişi ve kodlama sürecini saniyeler içinde bitirmesi', 'İfade yeteneği zayıf bireylerde yanıt oranını yükseltmesi', 'Grup karşılaştırmalarında kodlayıcı hatasını sıfırlaması'], 'Açık uçlu sorular katılımcıyı hazır kalıplara hapsetmez; araştırmacının kurgularken aklına gelmeyen derinlemesine temaları keşfetmesine olanak tanır.'),
  ('Binlerce kişilik ulusal bir saha taramasında açık uçlu sorular yerine kapalı uçlu maddelerin tercih edilmesinin birincil pratik nedeni hangisidir?', 'Sayısallaştırma ve istatistiksel çözümleme kolaylığı sağlaması', ['Katılımcıların konuyu yanlış anlama ihtimalini artırması', 'Derinlemesine klinik vaka öyküsü toplamayı zorunlu kılması', 'Seçeneklerin dışında kalan sıra dışı fikirleri kaydetmesi'], 'Kapalı uçlu sorular standart seçenekler sunduğundan büyük örneklemlerde hızlı yanıtlanır, düşük maliyetle kodlanır ve doğrudan analiz edilir.'),
  ('Yarı kapalı uçlu (hibrit) bir anket sorusu tasarlamak isteyen uzman, sabit seçenek listesinin sonuna ne tür bir ekleme yapmalıdır?', 'Açıklama satırı içeren \'Diğer (Lütfen belirtiniz)\' seçeneği', ['Yanıtlayıcıyı bir sonraki bölüme atlatan gizli yönlendirme kodu', 'Tüm şıkları aynı anda işaretlemeye zorlayan kontrol kutusu', 'Soru metnini başa döndüren zorunlu doğrulama anahtarı'], 'Sabit seçeneklerin kapsayamadığı durumlar için açık uçlu bir \'Diğer\' satırı eklemek, hem hız avantajını korur hem de veri kaybını önler.'),
  ('Sürücü belgesi olmayan bir katılımcıya \'Aracınızı haftada kaç kez yıkatırsınız?\' sorusunun yöneltilmesini engelleyen yönlendirici eleme maddesine ne ad verilir?', 'Filtre sorusu', ['Tuzak sorusu', 'Dolgu sorusu', 'Yansıtma sorusu'], 'Filtre (süzgeç) soruları, izleyen özel soruların yalnızca ilgili alt gruba (örneğin ehliyeti ve aracı olanlara) sorulmasını sağlar.'),
  ('Çevrimiçi anket yazılımlarında önceki yanıta bağlı olarak ilgisiz maddelerin ekranda hiç gösterilmeden geçilmesi düzeneği nasıl adlandırılır?', 'Atlama mantığı', ['Rastgele bloklama', 'Ters puanlama', 'Çapraz tablolama'], 'Atlama veya dallanma mantığı, filtre sorusuna verilen cevaba göre katılımcıyı otomatik olarak uygun soru bloğuna yönlendirir.'),
  ('Aynı anketin farklı yerlerinde biçimi değiştirilerek sorulan ve katılımcının rastgele işaretleme yapıp yapmadığını denetleyen maddelere ne denir?', 'Kontrol sorusu', ['Isınma sorusu', 'Demografik soru', 'Açılış sorusu'], 'Kontrol (tutarlılık) soruları, katılımcının soruları okuyarak samimi ve dikkatli yanıt verip vermediğini sınamak amacıyla forma yerleştirilir.'),
  ('Katılımcıdan beş farklı akıllı telefon özelliğini kendisi için en önemliden en önemsize doğru 1\'den 5\'e kadar numaralandırmasını isteyen soru tipi hangisidir?', 'Zorunlu sıralama sorusu', ['İki kutuplu evet-hayır sorusu', 'Serbest çağrışım cümle tamamlama', 'Bağımsız açık uçlu kompozisyon'], 'Sıralama (ranking) sorularında katılımcı maddeleri birbirleriyle kıyaslayarak öncelik sırasına dizer; bu nedenle her sıra numarası bir kez kullanılır.'),
  ('Aynı yanıt kategorilerini paylaşan çok sayıda maddenin satır ve sütunlar halinde tek bir tabloda sunulmasına anket tasarımında ne ad verilir?', 'Matris (ızgara) soru biçimi', ['Huni tekniği soru dizilimi', 'Projektif öykü tamamlama', 'Kart eşleştirme düzeneği'], 'Matris sorular, ortak derecelendirme seçeneklerine sahip maddeleri kompakt bir tabloda birleştirerek yerden ve zamandan tasarruf sağlar.'),
  ('Genel ve kapsamlı sorulardan başlayıp kademeli olarak daha dar ve özel konulara inen anket kurgulama stratejisine ne ad verilir?', 'Huni tekniği', ['Kelebek etkisi', 'Kartopu dizilimi', 'Mozaik tarama'], 'Huni diziliminde önce konuya genel bir giriş yapılır, katılımcının zihni ısındıkça spesifik davranış ve tutum sorularına geçilir.'),
  ('Laboratuvarda bir öğrencinin mikroskop altındaki hücre sayısını 0, 12, 24 biçiminde kaydetmesi neden eşit oranlı ölçmeye örnektir?', 'Sıfır değerinin hiç hücre bulunmadığını kesin olarak göstermesi', ['Hücrelerin türlerine göre farklı boyalarla renklendirilmesi', 'Sayım işleminin yalnızca iki gözlemci tarafından onaylanması', 'Sonuçların yüzdelik dilimler yerine harf notuyla bildirilmesi'], 'Adet/sayım verilerinde sıfır gerçek yokluktur ve 24 hücre, 12 hücrenin tam iki katıdır; dört işlem ve oranlama geçerlidir.'),
  ('Anketin başında katılımcının konuya ilgisini çekmek, gerginliğini azaltmak ve iletişimi başlatmak üzere konulan kolay sorulara ne ad verilir?', 'Isınma soruları', ['Eleme soruları', 'Sağlama soruları', 'Yansıtıcı sorular'], 'Isınma (buzkıran) soruları tehdit edici olmayan, kolayca yanıtlanabilen ve katılımcıyı ankete motive eden giriş maddeleridir.'),
  ('Kitaplıktaki eserleri roman, şiir, deneme ve biyografi biçiminde raflara ayıran bir kütüphanecinin yaptığı işlem ölçme kuramında nereye karşılık gelir?', 'Adlandırma düzeyinde sınıflama', ['Eşit aralıklı puanlama', 'Mutlak sıfırlı oranlama', 'Büyüklük sırasına dizme'], 'Edebi türlere göre ayırma işlemi niteliksel benzerlik ve farklılıklara dayanır; türler arasında nicel üstünlük veya eşit aralık bulunmaz.'),
  ('Sayısal değer istenen açık uçlu bir maddede (\'Günde ortalama ___ dakika kitap okursunuz?\') birim bilgisinin boşluğun yanına yazılmasının amacı nedir?', 'Bazı kişilerin saat, bazılarının dakika yazarak veri karmaşası yaratmasını önlemek', ['Katılımcıları toplum ortalamasının üzerinde bir sayı yazmaya yönlendirmek', 'Soru kökündeki dil bilgisi devrikliğini gizleyerek estetik görünüm sağlamak', 'Yanıtlayıcının okuma hızını saniye bazında gizlice test edebilmek'], 'Ölçü birimi açıkça belirtilmezse veriler farklı birimlerde (ör. 1 saat yerine 1, 60 dakika yerine 60) girilir ve analiz hatalı olur.'),
  ('Yüz yüze görüşmelerde çok seçenekli sorularda bellek yükünü azaltmak için görüşmecinin katılımcıya uzattığı yazılı yardımcı materyale ne denir?', 'Gösterim kartı', ['Onam belgesi', 'Kod kitabı', 'Örneklem çerçevesi'], 'Gösterim kartları, katılımcının seçenekleri hem duyup hem gözüyle görerek rahatça seçebilmesini sağlayan basılı kartlardır.'),
  ('Projektif cümle tamamlama (\'Bence iyi bir yönetici her zaman ...........\') maddeleri anket tasarımında hangi soru grubuna girer?', 'Yapılandırılmamış açık uçlu sorular', ['Zorunlu seçmeli dikotom maddeler', 'Sabit toplamlı oranlı ölçekler', 'Filtreli matris derecelendirmeler'], 'Cümle tamamlama maddelerinde hazır seçenek verilmez; bireyin boşluğu kendi zihinsel çağrışımlarıyla serbestçe doldurması beklenir.'),
  ('Bir konu bloğundan bambaşka bir konu bloğuna geçerken \'Şimdi de mahallenizdeki ulaşım olanaklarıyla ilgili birkaç sorumuz olacak\' gibi ifadeler eklemeye ne denir?', 'Geçiş (köprü) tümcesi kullanımı', ['Yönlendirici telkin uygulaması', 'Çift namlulu madde kurgusu', 'Sosyal onay tuzağı kurma'], 'Geçiş ifadeleri katılımcının zihnini yeni temaya hazırlar ve anketin mekanik bir sorgulama yerine doğal bir diyalog gibi ilerlemesini sağlar.'),
  ('Posta kodu veya T.C. kimlik numarası gibi çok basamaklı sayısal diziler istatistiksel veri yapısında nasıl ele alınmalıdır?', 'Matematiksel büyüklük taşımayan kategorik dizgeler olarak', ['Standart sapması ve çarpıklığı raporlanan sürekli değişkenler olarak', 'Mutlak sıfır noktasına sahip fiziksel miktar ölçümleri olarak', 'Aralıklarındaki farklar birbirine eşit olan psikometrik puanlar olarak'], 'Posta ve kimlik kodları rakamlardan oluşsa da yalnızca bölge veya birey tanımlar; nominal düzeydedir.'),
  ('Bir e-ticaret anketinde \'Son 6 ayda sitemizden iade işlemi yaptınız mı?\' sorusuna \'Hayır\' diyen birine hemen ardından \'İade kargo sürecimizden ne kadar memnun kaldınız?\' sorulması neyin eksikliğidir?', 'Koşullu dallanma ve filtreleme kurgusunun', ['İç tutarlılık katsayısı hesaplamasının', 'Ters kodlanmış negatif madde dengesinin', 'Eşit aralıklı ölçek başlangıç noktasının'], 'İade deneyimi olmayan birinden iade memnuniyeti istemek filtreleme hatasıdır ve katılımcıyı rastgele orta şıkkı işaretlemeye zorlar.'),
  ('Anket yönergesinde \'Bu araştırmada doğru veya yanlış cevap yoktur; önemli olan sizin kişisel görüşünüzdür\' cümlesinin vurgulanma nedeni nedir?', 'Değerlendirilme kaygısını azaltarak içten yanıt vermeyi kolaylaştırmak', ['Ölçeğin başarı testi olarak puanlanacağını katılımcıya bildirmek', 'Açık uçlu soruların gramer kurallarına göre notlandırılacağını belirtmek', 'Katılımcıların tüm maddelerde orta seçeneği işaretlemesini sağlamak'], 'Tutum ve görüş anketlerini bilgi sınavı sanan katılımcılar çekingen davranabilir; bu yönerge sınav kaygısını giderir.'),
  ('Çocuklarla veya okuma yazma bilmeyen gruplarla yürütülen saha çalışmalarında kapalı uçlu derecelendirme seçenekleri nasıl uyarlanır?', 'Yüz ifadeleri (gülen-üzgün suratlar) veya kademeli büyüyen grafik sembollerle', ['Akademik terimlerin Latince karşılıkları parantez içinde verilerek', 'Tüm sorular yirmi satırlık açık uçlu kompozisyon ödevine çevrilerek', 'Seçenek kutuları kaldırılıp yalnızca yüzdelik olasılık hesabı istenerek'], 'Sözel okuma becerisi sınırlı gruplarda Wong-Baker yüz ölçeği gibi piktogramlar ve görsel semboller bilişsel erişilebilirliği sağlar.'),
  ('Anket formunun kapak açıklaması veya bilgilendirilmiş onam metninde aşağıdakilerden hangisinin yer alması etik ve metodolojik bir zorunluluktur?', 'Araştırmanın amacı, tahmini süresi, gizlilik güvencesi ve gönüllülük ilkesi', ['Araştırmacının doğrulamayı umduğu tüm istatistiksel yönlü hipotezler', 'Diğer katılımcıların adları, telefon numaraları ve verdikleri örnek yanıtlar', 'Beklenen sonuçlara uymayan yanıtların cezalandırılacağına dair uyarı'], 'Katılımcıya çalışmanın konusu, ne kadar süreceği, verilerin gizli tutulacağı ve istediği an ayrılabileceği açıkça bildirilmelidir; ancak hipotezler yönlendirme yapmamak için açık edilmez.'),
  ('Bir araştırmacı katılımcıların siyasi parti tercihini 1=A Partisi, 2=B Partisi, 3=C Partisi diye kodlayıp SPSS\'te ortalamayı 2,14 bulmuştur. Bu işlem neden hatalıdır?', 'Atanan rakamların nicel büyüklük taşımayan keyfî etiketler olmasından ötürü', ['Siyasi parti sayısının en az beş olmadan ortalamanın hesaplanamamasından ötürü', 'Ondalıklı sonucun yukarıya yuvarlanarak 3 yapılması gerektiğinden ötürü', 'Parti tercihinin mutlak sıfır noktasına sahip oranlı değişken olmasından ötürü'], 'Yazılımlar sayısal kodların ölçme düzeyini sorgulamadan işlem yapar; nominal kodların ortalamasını almak istatistiksel açıdan tamamen anlamsızdır.'),
  ('Anket formunun sayfa düzeninde soru kökü bir sayfanın en altında kalırken seçeneklerin arka sayfaya taşması neden sakıncalıdır?', 'Görsel bütünlüğü bozarak katılımcının eksik şık okumasına yol açması', ['Baskı makinesinin mürekkep dağılımını yarı yarıya azaltması', 'Sorunun ölçme düzeyini sıralamadan sınıflamaya düşürmesi', 'Açık uçlu yanıtların kelime sayısını yapay olarak artırması'], 'Soru metni ile tüm seçenekleri tek bir görsel blok olarak aynı sayfada tutulmalıdır; bölünme olduğunda arka sayfadaki şıklar gözden kaçabilir.'),
  ('Sıralamalı bir ölçekte \'1=Çok Kötü, 2=Kötü, 3=Orta, 4=İyi, 5=Çok İyi\' yerine \'1=Çok İyi ... 5=Çok Kötü\' ters yönlü numaralandırma kullanılırsa raporlamada neye dikkat edilmelidir?', 'Yüksek puanın olumsuzluğu temsil ettiğinin tablo altında açıkça belirtilmesine', ['Elde edilen tüm sayıların karekökü alınarak negatif işaret eklenmesine', 'Mod ve medyan yerine yalnızca harmonik ortalamanın sunulmasına', 'Verilerin sınıflama ölçeğine çevrilerek büyüklük sırasının silinmesine'], 'Sezgisel olarak yüksek sayılar fazlalık/olumluluk çağrıştırır; ters yönlü kodlama yapılmışsa yanlış yorumu önlemek için kodlama yönü net biçimde açıklanmalıdır.'),
  ('Çoktan seçmeli bir bilgi testinde doğru yanıtın yanına yazılan çeldiricilerin (yanlış seçeneklerin) temel işlevi nedir?', 'Konuyu tam bilmeyenlerle gerçekten bilenleri birbirinden ayırt etmek', ['Bilen öğrencileri şaşırtarak sınav ortalamasını sıfıra yaklaştırmak', 'Şans başarısını %25\'ten %75 düzeyine yükseltmek', 'Soru kökünde verilmeyen ek kuramsal bilgileri öğretmek'], 'İyi bir çeldirici, kavram yanılgısı olan veya konuyu bilmeyen kişiye makul görünerek şansla doğru bulmayı azaltır; tam bileni ise yanıltmaz.'),
  ('Anket sonunda yer alan \'Eklemek istediğiniz başka bir görüş veya öneriniz var mı?\' şeklindeki kapanış sorusunun psikolojik ve metodolojik işlevi nedir?', 'Katılımcıya söz hakkı tanıyarak kapalı şıkların kaçırdığı önemli noktaları yakalamak', ['Önceki tüm kapalı uçlu maddelerin puanlarını geçersiz kılmak', 'Katılımcının okuma hızını ölçerek dikkat puanı hesaplamak', 'Demografik sorulara verilen yanıtların doğruluğunu kanıtlamak'], 'Son açık uçlu soru hem katılımcıda sesinin duyulduğu hissini yaratır hem de ankette değinilmeyen kritik saha gözlemlerini toplar.'),
  ('Anket tasarımında \'kod kitabı\' (codebook) hazırlamanın veri yönetimi açısından birincil görevi aşağıdakilerden hangisidir?', 'Her değişkenin adını, soru metnini, sayısal kod karşılıklarını ve kayıp veri kodlarını belgelemek', ['Katılımcılara dağıtılacak hediye çeklerinin seri numaralarını gizlemek', 'Literatür taramasında okunan makalelerin özetlerini kronolojik sıralamak', 'Alan çalışmasında görev yapan anketörlerin ulaşım güzergâhlarını çizmek'], 'Kod kitabı, veri setindeki sütunların ve sayıların (ör. 1=Kadın, 2=Erkek, 99=Yanıtsız) ne anlama geldiğini gösteren temel başvuru kılavuzudur.'),
  ('Rensis Likert tarafından 1932 yılında geliştirilen derecelendirme tekniğinde katılımcıların tepki verdiği temel birim aşağıdakilerden hangisidir?', 'Olumlu veya olumsuz yargı bildiren tutum cümleleri', ['Sadece tek kelimelik zıt anlamlı sıfat çiftlerinden oluşan kutuplar', 'Hakem kurulu tarafından ağırlık puanı atanmış tarihsel olay özetleri', 'Sıfır noktası olmayan artı ve eksi beş basamaklı sayı merdivenleri'], 'Likert tipi ölçeklerde katılımcılara açık bir yargı içeren düz ifadeler (maddeler) verilir ve bu ifadelere katılma derecelerini belirtmeleri istenir.'),
  ('Charles Osgood ve arkadaşlarının kavramların çağrışımsal (konotatif) anlamlarını ölçmek üzere geliştirdiği, iki uçta \'İyi — Kötü\', \'Güçlü — Zayıf\' gibi zıt sıfatların yer aldığı araç hangisidir?', 'Anlamsal farklılaştırma ölçeği', ['Birikimli Guttman ölçeği', 'Eşit görünen aralıklar ölçeği', 'Sosyal uzaklık basamakları'], 'Osgood\'un semantik diferansiyel (anlamsal farklılaştırma) tekniğinde genellikle 7 aralıklı bir çizginin iki ucuna zıt kutuplu sıfat çiftleri konur.'),
  ('Emory Bogardus tarafından etnik, dini veya ulusal gruplara yönelik önyargı ve yakınlık isteğini ölçmek amacıyla geliştirilen klasik ölçek hangisidir?', 'Sosyal mesafe ölçeği', ['Mesleki tükenmişlik envanteri', 'Bilişsel çelişki matrisi', 'Duygusal zekâ derecelendirmesi'], 'Bogardus ölçeği \'Evlilik yoluyla akrabalığa kabul ederim\'den \'Ülkemden çıkarılmasını isterim\'e uzanan Guttman benzeri kademeli yakınlık basamakları içerir.'),
  ('Uç yanıt verme yanlılığı (extreme response style) gösteren bir katılımcı profili 7\'li Likert ölçeğinde nasıl bir işaretleme eğilimi sergiler?', 'Ilımlı ara seçeneklerden kaçınarak sürekli 1 veya 7 numaralı uç kutuları tercih eder', ['Tüm sorularda yalnızca tam ortadaki 4 numaralı seçeneği işaretler', 'Sadece çift numaralı olan 2, 4 ve 6 basamaklarını sırayla doldurur', 'Maddelerin yarısını boş bırakıp diğer yarısına kendi cümlelerini yazar'], 'Kişilik veya kültürel iletişim tarzından kaynaklanan uç yanıt stili, tutum şiddeti orta düzeyde olsa bile sürekli \'Kesinlikle\' uçlarını seçme alışkanlığıdır.'),
  ('Bir ölçekte \'1=Kesinlikle Katılıyorum ... 5=Kesinlikle Katılmıyorum\' (azalan sıra) yerine \'1=Kesinlikle Katılmıyorum ... 5=Kesinlikle Katılıyorum\' (artan sıra) kullanmanın sezgisel üstünlüğü nedir?', 'Sayısal büyüklük artışıyla onaylama/tutum şiddeti artışının aynı yönde eşleşmesi', ['İstatistiksel testlerde serbestlik derecesini beş birim artırması', 'Olumsuz maddelerin ters kodlanması zorunluluğunu ortadan kaldırması', 'Katılımcıların anketi doldurma süresini bir dakikanın altına indirmesi'], 'Zihinsel sayı doğrusu soldan sağa büyüdüğü ve yüksek rakam daha yüksek katılmayı simgelediği için artan puanlama hem katılımcı hem araştırmacı için daha az kafa karıştırıcıdır.'),
  ('Aynı anket kitapçığı içinde birinci ölçekte \'1=Kesinlikle Katılmıyorum, 5=Kesinlikle Katılıyorum\', ikinci ölçekte ise tam tersi \'1=Kesinlikle Katılıyorum, 5=Kesinlikle Katılmıyorum\' düzeni kullanılırsa ne olur?', 'Alışkanlıkla işaretleme yapan katılımcılar yön değişimini fark etmeyerek tam tersi yanıtlar verir', ['İki ölçek arasındaki korelasyon katsayısı hatasız biçimde gerçek değerine ulaşır', 'Katılımcıların dikkat düzeyi tavan yaparak okuma hataları tamamen silinir', 'Veri girişi aşamasında kod kitabı hazırlamaya hiç gerek kalmaz'], 'Aynı form içinde ölçek yönünü tersyüz etmek ciddi yanıtlayıcı hatası doğurur; tüm anket boyunca derecelendirme yönü tutarlı tutulmalıdır.'),
  ('Ancak pratikte hem Likert ters maddelerinde hem de Osgood ters kutuplarında yön değiştirme yapıldığında veri analizi öncesinde araştırmacının mutlaka denetlemesi gereken adım nedir?', 'Ters yönlü maddelerin kod kitabına uygun biçimde yeniden kodlanıp aynı kuramsal yöne çevrildiğini doğrulamak', ['Ters çevrilen maddelerin standart sapmalarını ikiyle bölerek küçültmek', 'Düz maddelerle ters maddeleri ayrı ayrı örneklemlermiş gibi bağımsız t-testine sokmak', 'Yönü değiştirilen tüm sıfat çiftlerini tablolardan çıkarıp gizlemek'], 'Ters kutuplu maddeler analiz öncesi tek bir ortak yöne (ör. yüksek puan = olumlu imaj) döndürülmezse ortalama ve güvenirlik hesapları tamamen hatalı çıkar.'),
  ('Puanlama anahtarında \'Yüksek puanlar siber zorbalığa yönelik yüksek farkındalığı göstermektedir\' bilgisi verilen bir ölçekte, \'Sosyal medyada sahte hesapla alay etmek zararsız bir şakadır\' maddesi nasıl işlenmelidir?', 'Düşük farkındalığı ifade ettiği için analizden önce mutlaka ters kodlanmalıdır', ['Olumlu bir mizah duygusunu ölçtüğü için olduğu gibi düz toplanmalıdır', 'Farkındalıkla ilgisi olmadığı gerekçesiyle ortalaması sıfır yapılmalıdır', 'Yalnızca en yüksek puanı verenlerin verisi ikiyle çarpılmalıdır'], 'Alay etmeyi \'zararsız şaka\' görmek düşük farkındalık göstergesidir; toplam puan yüksek farkındalığı temsil edeceğinden bu madde ters çevrilmelidir.'),
  ('Tutumun bilişsel (inanç/bilgi), duyuşsal (duygu/hoşlanma) ve davranışsal (eylem eğilimi) üç bileşenini kapsayan bir ölçekte \'Matematik dersinde tahtaya kalktığımda kalbim sıkışır ve huzursuz olurum\' maddesi hangi bileşene odaklanır?', 'Duyuşsal (heyecansal) bileşen', ['Salt bilişsel bilgi bileşeni', 'Demografik geçmiş bileşeni', 'Sosyal mesafe bileşeni'], 'Kaygı, korku, sevme, hoşlanma ve huzursuzluk gibi duygusal tepkileri ifade eden maddeler tutumun duyuşsal boyutunu temsil eder.'),
  ('Aynı matematik tutum ölçeğinde yer alan \'Boş zamanlarımda zor matematik bulmacaları çözmeye gönüllü olarak vakit ayırırım\' ifadesi tutumun hangi öğesini örnekler?', 'Davranışsal eğilim bileşeni', ['Yalnızca bilişsel kanı bileşeni', 'Fizyolojik refleks bileşeni', 'Kalıtsal yetenek bileşeni'], 'Tutum nesnesine yaklaşma, zaman ayırma veya ondan kaçınma yönündeki somut eylem niyet ve alışkanlıkları davranışsal bileşendir.'),
  ('\'Matematiksel düşünme becerisi mühendislik ve ekonomi alanlarında mesleki başarı için gereklidir\' yargısı ise üçlü tutum modelinin hangi boyutuna girer?', 'Bilişsel (inanç ve kanaat) bileşeni', ['Duyuşsal coşku bileşeni', 'Psikomotor kas bileşeni', 'Güdüsel dürtü bileşeni'], 'Nesnenin yararı, özellikleri veya sonuçları hakkındaki akılcı düşünce ve inanç önermeleri tutumun bilişsel boyutunu oluşturur.'),
  ('Bir anket formunda yer alan \'Belediyemizin park temizliği ve toplu taşıma sefer sıklığından memnun musunuz?\' maddesi hangi temel soru yazım kusurunu taşımaktadır?', 'Çift namlulu (bileşik) soru yapısı', ['Sosyal beğenilirlik baskısı yaratan tehditkâr ifade', 'Akademik jargon içeren anlaşılmaz teknik terim kullanımı', 'Mutlak sıfır noktasını kaydıran oranlı ölçek hatası'], 'Tek bir soruda hem \'park temizliği\' hem \'toplu taşıma sıklığı\' sorulmuştur; parklardan memnun olup otobüslerden memnun olmayan katılımcı tek bir şıkla gerçek görüşünü bildiremez.'),
  ('Çift namlulu (double-barreled) bir anket maddesini düzeltmek isteyen araştırmacının izlemesi gereken en doğru yol aşağıdakilerden hangisidir?', 'Maddedeki iki ayrı konuyu bölerek bağımsız iki soru haline getirmek', ['Soru kökündeki \'ve\' bağlacını silip yerine \'veya\' bağlacını yerleştirmek', 'Yanıt seçeneklerinin sayısını beş basamaktan yedi basamağa yükseltmek', 'Soruyu formun en sonundaki demografik bilgiler bölümüne kaydırmak'], 'Bileşik sorularda \'veya\' kullanmak belirsizliği çözmez (hangisine evet dendiği yine bilinmez); çözüm her bir önermeyi ayrı bir madde olarak sormaktır.'),
  ('\'Sorumlu her vatandaş gibi siz de geri dönüşüm kutularını düzenli kullanıyor musunuz?\' biçiminde kurgulanan bir soru hangi kusura örnektir?', 'Yönlendirici ve yüklü (loaded) ifade kullanımı', ['Kapsayıcılık ilkesini bozan eksik seçenek listesi', 'Çift olumsuz eklerden kaynaklanan sözdizimsel karmaşa', 'Bellek geri getirme süresini aşan zamansal teleskoplama'], 'Sorunun başındaki \'Sorumlu her vatandaş gibi\' ifadesi normatif bir baskı kurarak \'Hayır\' yanıtını sorumsuzlukla eşitlemekte ve katılımcıyı \'Evet\' demeye itmektedir.'),
  ('\'Okullarda cep telefonu kullanımının yasaklanmaması gerektiğine katılmıyor musunuz?\' maddesinin yanıtlayıcıda kafa karışıklığı yaratmasının nedeni nedir?', 'Çift olumsuzluk içermesi yüzünden mantıksal yönün bulanıklaşması', ['Cep telefonu markalarının seçeneklerde tek tek sıralanmamış olması', 'Yalnızca lise öğrencilerinin anlayabileceği argo kelimeler barındırması', 'Soru kökünün herhangi bir zaman dilimiyle sınırlandırılmamış olması'], 'Hem \'yasaklanmaması\' hem \'katılmıyor musunuz\' olumsuz yapılarını bir arada kullanmak bilişsel işlem yükünü artırır; katılımcı yasağı desteklemek için \'Evet\' mi \'Hayır\' mı diyeceğini şaşırır.'),
  ('Halk sağlığı taramasında yetişkinlere yöneltilen \'Son bir ayda antihipertansif farmakoterapi rejiminize adherans gösterdiniz mi?\' sorusundaki temel tasarım hatası nedir?', 'Hedef kitlenin günlük diline yabancı teknik jargon içermesi', ['Bir aylık sürenin insan belleği için hatırlanması imkânsız olması', 'İki ayrı hastalığı tek bir cümle içinde birleştirerek sorması', 'Katılımcıyı yasa dışı bir davranışı itiraf etmeye zorlaması'], 'Sıradan katılımcılar \'antihipertansif farmakoterapi\' ve \'adherans\' terimlerini bilmeyebilir; soru \'Tansiyon ilaçlarınızı doktorun önerdiği düzende aldınız mı?\' şeklinde sadeleştirilmelidir.'),
  ('Yaş gruplarını \'18-25\', \'25-35\', \'35-45\' biçiminde sunan kapalı uçlu bir soruda 25 yaşındaki bir katılımcının yaşadığı kararsızlık hangi ilkenin ihlalinden doğar?', 'Seçeneklerin birbirini dışlaması (çakışmazlık) ilkesinin', ['Seçeneklerin tüm evreni tüketmesi (kapsayıcılık) ilkesinin', 'Soru kökünün tarafsız ve yüksüz bir dille yazılması ilkesinin', 'Hassas soruların huni tekniğiyle sona bırakılması ilkesinin'], 'Sınır değer olan 25 hem birinci hem ikinci aralıkta yer aldığı için kategoriler kesişmektedir; doğru yazım \'18-24\', \'25-34\', \'35-44\' şeklinde ayrık olmalıdır.'),
  ('Çalışma durumunu soran bir maddede yalnızca \'Tam zamanlı çalışan\', \'Yarı zamanlı çalışan\' ve \'Emekli\' şıklarının verilmesi hangi kuralı bozar?', 'Kapsayıcılık (tüketici olma) kuralını', ['Çift namlulu ifadelerden kaçınma kuralını', 'Kronolojik sıra düzenini koruma kuralını', 'Ters madde dengesini gözetme kuralını'], 'Öğrenciler, iş arayanlar veya ev kadınları listede kendilerine uygun hiçbir kategori bulamayacağı için seçenek kümesi evreni tüketmemektedir.'),
  ('Madde içeriğinden bağımsız olarak katılımcının kendisine yöneltilen her türlü yargıyı onaylama ve \'Evet / Katılıyorum\' yönünde tepki verme eğilimine ne denir?', 'Onaylama yanlılığı', ['Sosyal mesafe daraltma yanlılığı', 'Geriye dönük hatırlama yanlılığı', 'Gözlemci beklenti yanlılığı'], 'Onaylama tepki seti (yea-saying), nezaket normları, bilişsel tembellik veya otoriteye uyum nedeniyle önermelere içerikten bağımsız katılma eğilimidir.'),
  ('Bunun tam tersine, önermenin konusu ne olursa olsun katılımcının sürekli itiraz etme ve \'Hayır / Katılmıyorum\' seçeneklerine yönelme alışkanlığı nasıl adlandırılır?', 'Reddetme yanlılığı', ['Tavan etkisi sıkışması', 'Öncelik konumu yanlılığı', 'Merkezi eğilim hatası'], 'Muhalif tepki seti (nay-saying), bireyin sunulan genel yargılara şüpheyle yaklaşıp sistematik olarak olumsuz uçları tercih etmesidir.'),
  ('Katılımcının vergi kaçırma, önyargı, alkol kullanımı veya oy verme gibi konularda gerçek durumu yerine toplumun hoş karşılayacağı yanıtı vermesine ne ad verilir?', 'Sosyal beğenilirlik (arzu edilirlik) yanlılığı', ['Örnekleme çerçevesi kapsama yanlılığı', 'Araçsal kalibrasyon kayması hatası', 'Matematiksel yuvarlama ve kesme hatası'], 'Sosyal beğenilirlik yanlılığında birey ayıplanmamak veya iyi bir izlenim bırakmak amacıyla normlara uygun davranışları abartır, hoş görülmeyenleri gizler.'),
  ('Derecelendirme ölçeklerinde bazı katılımcıların içerikten bağımsız olarak sürekli \'1\' ve \'7\' gibi en uç basamakları tercih etmesi eğilimine ne ad verilir?', 'Uç tepki yanlılığı (extreme response style)', ['Merkezi toplanma yanlılığı (midpoint style)', 'Öncelik konumu yanlılığı (primacy effect)', 'Kayıp gözlem atama yanlılığı (imputation bias)'], 'Uç tepki stili, bireyin ılımlı ara dereceleri kullanmayıp dünyayı siyah-beyaz kesinlikte kodlayarak hep en alt ve en üst kutuları işaretlemesidir.'),
  ('Yöneticilerin çalışan performansını değerlendirdiği bir ölçekte, yöneticinin kimseyle kötü olmamak veya ayırt etmekten çekinmek için herkese \'3 - Orta\' puan vermesi hangi hatadır?', 'Merkezi eğilim (orta noktaya yığılma) hatası', ['Sertlik ve acımasızlık (severity) hatası', 'Mantıksal çağrışım ve hale (halo) hatası', 'Zamansal yakınlık (recency) hatası'], 'Merkezi eğilim hatasında puanlayıcı uç değerlendirmelerden kaçınarak tüm bireyleri ölçeğin orta noktasında toplar; bu da varyansı yok eder.'),
  ('Bir öğretmenin öğrencinin yalnızca çok düzgün el yazısına veya nazik konuşmasına bakarak onun matematik, fen ve resim yeteneklerinin tamamına yüksek puan vermesi hangi yanlılıktır?', 'Hale (halo) etkisi yanlılığı', ['Boynuz (horn) ters izlenim yanlılığı', 'Sosyal mesafe daraltma yanlılığı', 'Rastgele ölçme hatası dağılımı'], 'Hale etkisinde bireyin göze çarpan tek bir olumlu özelliği veya genel olumlu izlenimi, birbiriyle ilgisiz diğer tüm alt boyutların puanlarını yukarı çeker.'),
  ('Performans veya tutum derecelendirmelerinde bir değerlendiricinin standartların çok üzerinde iyimser davranarak gruptaki neredeyse herkese 5 üzerinden 4 ve 5 vermesi hangi puanlayıcı yanlılığıdır?', 'Cömertlik (bol not / leniency) yanlılığı', ['Katılık (kıt not / severity) yanlılığı', 'Orta noktaya kaçış (central tendency) yanlılığı', 'Karşıtlık (kontrast) kıyaslama yanlılığı'], 'Cömertlik hatasında değerlendirici aşırı hoşgörülü davranarak puanları üst uca yığar ve tavan etkisi oluşturur; tersi ise katılık (severity) hatasıdır.'),
  ('Anket formunu büyük örnekleme uygulamadan önce hedef kitleye benzer 15-30 kişilik küçük bir grupta deneyerek aksayan soruları saptama aşamasına ne ad verilir?', 'Pilot uygulama (ön deneme / pretesting)', ['Sonradan ağırlıklandırma (post-stratification)', 'Doğrulayıcı faktör analizi (confirmatory analysis)', 'Meta-analitik etki birleştirme (meta-analysis)'], 'Ön deneme (pilot test), masa başında fark edilemeyen anlaşılmaz kelimeleri, bozuk filtreleri ve süreyi sahaya çıkmadan önce düzeltmeyi sağlar.'),
  ('\'Geçen hafta sonu kütüphaneye gitmediniz, değil mi?\' biçimindeki ek sorulu (tag question) cümle yapısı neden hatalı bir anket sorusudur?', 'Onaylatma ekiyle katılımcıyı \'gitmediği\' yönündeki cevabı tasdik etmeye zorladığı için', ['Hafta sonu kavramının kaç günden oluştuğu toplumda hiç bilinmediği için', 'Kütüphane kelimesinin yabancı kökenli teknik bir terim sayıldığı için', 'Aynı cümlede hem sinema hem kütüphane davranışını birlikte sorduğu için'], '\'...değil mi?\', \'...öyle değil mi?\' gibi onaylatma ekleri güçlü bir yönlendirme (leading) barındırır ve karşıt cevap vermenin sosyal maliyetini yükseltir.'),
  ('Yüz yüze yapılan bir saha araştırmasında anketörün giyimi, ses tonu, mimikleri veya başını sallayarak bazı yanıtlara onay vermesi hangi hata kaynağını doğurur?', 'Görüşmeci (anketör) yanlılığını', ['Örnekleme çerçevesi daralmasını', 'Kapsam geçerliği eksikliğini', 'Çoklu doğrusal bağlantı sorununu'], 'Görüşmeci etkisi, anketörün sözel veya sözel olmayan tepkilerinin katılımcıyı belirli bir yönde yanıt vermeye sevk etmesidir; standart görüşmeci eğitimiyle önlenir.'),
  ('Anket formunun sayfa tasarımında soru numarası ile yanıt kutularının arasına çok geniş boşluk bırakılması ve kılavuz çizgi konulmaması hangi hatayı tetikler?', 'Göz kayması sonucu katılımcının bir üst veya bir alt satırın kutucuğunu işaretlemesi', ['Sorunun dil bilgisi yapısının olumludan olumsuza doğru kendiliğinden değişmesi', 'Açık uçlu soruların kapalı uçlu sorulara göre daha yüksek güvenirlik vermesi', 'Örneklemin ana kütleyi temsil etme gücünün istatistiksel olarak ikiye katlanması'], 'Dillman\'ın görsel tasarım ilkelerine göre (yakınlık ve hizalama yasası), soru metni ile yanıt alanı görsel bütünlük taşımalı ve satırlar açık renk şeritlerle ayrılmalıdır.'),
  ('Bir kağıt ankette bir sorunun kök metninin sayfanın en altında kalması, yanıt seçeneklerinin ise arka sayfanın başında yer alması ne tür bir kusurdur?', 'Bölünmüş soru düzeni nedeniyle tüm şıklar görülmeden eksik okumayla yanıt verilmesi', ['Kâğıt tasarrufu sağlandığı için baskı maliyetinin yarı yarıya düşürülmesi', 'Öncelik ve sonralık etkilerinin birbirini tam olarak sıfırlayıp dengelemesi', 'Katılımcının arka sayfaya geçtiğinde önceki tüm yanıtlarını silmek zorunda kalması'], 'Bir soru ve ona ait tüm yanıt seçenekleri asla iki sayfaya bölünmemelidir; katılımcı ilk sayfanın altındaki ilk iki şıkkı tüm seçenekler sanıp işaretleyebilir.'),
  ('\'Belediye başkanının performansını nasıl değerlendiriyorsunuz?\' sorusunda seçeneklerin \'Mükemmel, Çok iyi, İyi, Orta, Kötü\' biçiminde verilmesi neden kusurludur?', 'Üç olumlu seçeneğe karşılık yalnızca bir olumsuz seçenek sunarak ölçeği pozitif yöne kaydırdığı için', ['Seçenek sayısının beş basamak olması istatistiksel ortalamayı imkânsız kıldığı için', 'Sıfatların tamamı Türkçe kökenli kelimelerden seçildiği için anlaşılması zorlaştığından', 'Belediye başkanının adı soru kökünde açıkça belirtilmediği için belirsizlik doğurduğundan'], 'Dengesiz yanıt ölçeği (unbalanced scale), olumlu şıkları çoğaltarak dağılımı yapay biçimde memnuniyet lehine şişirir; olumlu ve olumsuz kutup sayıları eşit (simetrik) olmalıdır.'),
  ('Bilişsel ön test aşamasında \'uzman paneli incelemesi\' (expert review) yapılırken ölçme uzmanından ve alan uzmanından beklenen katkılar nasıl farklılaşır?', 'Alan uzmanı kavramsal kapsam uygunluğunu, ölçme uzmanı ise madde yapısı ve tepki ölçeği kusurlarını denetler', ['Alan uzmanı sayfa kenar boşluklarını ölçerken, ölçme uzmanı katılımcıların telefon numaralarını doğrular', 'Her iki uzman grubu da maddeleri hiç okumadan yalnızca anketin başlık rengine karar verir', 'Ölçme uzmanı kuramsal literatürü yazarken, alan uzmanı bilgisayar yazılımının kodlarını derler'], 'Konu alanı uzmanı maddenin kuramsal yapıyı temsil edip etmediğine bakar; psikometri/anket uzmanı ise çift namlulu ifade, yönlendirme ve şık uyumsuzluğunu yakalar.'),
  ('\'Maaşınızdan ne kadar memnunsunuz?\' sorusunu çalışmayan emeklilerin ve öğrencilerin de bulunduğu genel nüfusa yöneltmeden önce ne yapılmalıdır?', 'Gelir getirici bir işte çalışıp çalışmadığını belirleyen bir filtre sorusu konulmalıdır', ['Maaş kelimesinin yanına harçlık ve borç kelimeleri eklenerek cümle uzatılmalıdır', 'Seçeneklerin tamamı olumsuz sıfatlardan seçilerek memnuniyet sıfırlanmalıdır', 'Soru metni İngilizceye çevrilerek uluslararası standartlara uyarlanmalıdır'], 'Ücretli bir işte çalışmayan kişiye maaş memnuniyeti sormak geçersiz varsayım kusurudur; filtre sorusuyla yalnızca çalışanlara yönlendirilmelidir.'),
  ('\'Sınıfınızda kopya çeken öğrencileri öğretmene bildirmemek ahlaksızlık mıdır?\' sorusundaki \'ahlaksızlık\' sözcüğü neden kusurlu bir madde yazımıdır?', 'Ağır duygusal ve ahlaki yargı yüklü (loaded) bir etiket kullanarak katılımcıyı savunmaya ittiği için', ['Türkçe sözlükte dört heceden uzun kelimelerin anketlerde kullanılması önerilmediği için', 'Öğretmen ve öğrenci kelimeleri aynı cümlede geçtiğinde anlam belirsizliği doğduğu için', 'Kopya çekme davranışının yalnızca üniversite düzeyinde görülen bir sorun olması nedeniyle'], '\'Ahlaksızlık, ihanet, aptallık, cinayet\' gibi aşırı duygusal yüklü kelimeler soğukkanlı tutum ölçümünü bozar ve tepkisel yanıtlar doğurur.'),
  ('Buna karşılık katılımcı duraksadığında anketörün \'Yani siz de mahallenin güvenli olduğunu söylüyorsunuz herhalde?\' demesi hangi kural ihlalidir?', 'Yönlendirici sondajlamayla görüşmeci yanlılığı yaratma', ['Gösterim kartını zamanından önce masadan kaldırma', 'Demografik kota sınırlarını saha sırasında aşma', 'Açık uçlu yanıtı kelime kelimesine tutanağa geçirme'], 'Anketörün duraksayan katılımcının ağzına belirli bir yanıtı koyması standartlaşmayı yıkar ve yapay onay üretir.'),
  ('Bir iş yerinde \'Yöneticiniz adil kararlar alır mı?\' sorusunun çalışanlara sicil numaralarını yazmaları istenen basılı bir formla dağıtılması öncelikle hangi sorunu doğurur?', 'Misilleme ve zarar görme korkusuyla gerçek olumsuz düşüncelerin gizlenmesi', ['Sicil numaralarının aritmetik ortalamasının tutum puanına yanlışlıkla eklenmesi', 'Çalışanların tamamının yöneticilerine en düşük puanı vererek taban etkisi yaratması', 'Formdaki tüm kapalı uçlu maddelerin açık uçlu kompozisyon sorusuna dönüşmesi'], 'Hiyerarşik güç ilişkisi bulunan ortamlarda kimlik tespiti yapılabilmesi anonimliği ortadan kaldırır ve yapay yüksek memnuniyet (korku kaynaklı yanlılık) üretir.'),
  ('\'Mahallenizdeki gürültü kirliliği geçen yıla göre arttı mı, azaldı mı?\' sorusunda üçüncü bir doğal olasılığın unutulmuş olması hangi kusurdur?', '\'Aynı kaldı / Değişmedi\' durağan durum seçeneğinin şıklara eklenmemesi', ['Gürültü şiddetinin desibel ölçer cihazıyla evlerde tek tek kayıt altına alınmaması', 'Mahalle sınırlarının harita koordinatlarıyla soru kökünde tanımlanmaması', 'Geçen yıl ifadesinin miladi takvime göre mi hicri takvime göre mi olduğunun yazılmaması'], 'Değişim yönü sorulan karşılaştırma maddelerinde yalnızca \'arttı\' ve \'azaldı\' vermek, hiçbir değişim gözlemlemeyen kişileri yapay bir değişim bildirmeye zorlar.'),
  ('\'İş yerinizdeki yemekhane hizmetlerinden ne sıklıkla memnun kalıyorsunuz?\' sorusunda \'Çok memnunum — Hiç memnun değilim\' şıklarının verilmesi neden hatalıdır?', 'Soru kökü \'ne sıklıkla\' diye sıklık sorarken şıkların şiddet/derece bildirmesi', ['Yemekhane hizmetlerinin çalışanlar tarafından değerlendirilmesinin etik dışı olması', 'Memnuniyet kavramının yalnızca açık uçlu mülakatlarla araştırılabilmesi', 'Şık sayısının tek sayı yerine çift sayı olarak belirlenmemiş olması'], '\'Ne sıklıkla\' köküne \'Her zaman, Sık sık, Bazen, Nadiren, Hiçbir zaman\' uyar; \'Çok memnunum\' şıkları kullanılacaksa kök \'Ne derece memnunsunuz?\' olmalıdır.'),
  ('Anket formunun görsel düzeninde ÖNEMLİ veya DEĞİL gibi tek bir kritik kelimenin büyük harfle ya da altı çizili yazılması hangi durumda doğru bir tasarım kararıdır?', '\'Aşağıdakilerden hangisi bu kapsamda DEĞİLDİR?\' veya \'Son 7 gün içinde\' gibi gözden kaçması kolay sınırlandırıcı ifadelerde', ['Araştırmacının katılımcıların seçmesini istediği tek bir seçeneği diğerlerinden öne çıkarmak istediğinde', 'Yönlendirici bir sorudaki duygusal sıfatların katılımcı üzerinde daha sert baskı kurması gerektiğinde', 'Anketteki tüm kelimelerin ve tüm seçeneklerin baştan sona büyük harflerle dizildiği sayfalarda'], 'Olumsuz soru kökleri veya değişen zaman pencereleri (son 1 hafta / son 1 yıl) hızlı okumada atlanabilir; tipografik vurgu yalnızca doğru anlamayı korumak için kullanılır, şık yönlendirmek için değil.'),
  ('Yanıtlayıcıların anketin son sayfalarındaki açık uçlu sorulara ilk sayfalardakine kıyasla çok daha kısa ve baştan savma yanıtlar yazması hangi etkiyle açıklanır?', 'Anket yorgunluğu (respondent fatigue) ve tükenen motivasyon etkisiyle', ['Son sayfalardaki kâğıt dokusunun kalem mürekkebini daha az tutmasıyla', 'Katılımcıların anket ilerledikçe dil bilgisi kurallarını tamamen unutmasıyla', 'Açık uçlu soruların yalnızca anketin ilk maddesi olduğunda kodlanabilmesiyle'], 'Uzayan anketlerde bilişsel enerji azalır (burden/fatigue); sonlara kalan açık uçlu veya karmaşık matris sorularda yetinmecilik ve boş bırakma artar.'),
  ('\'Sigarayı bırakmayı denediniz mi?\' sorusuna \'Evet\' diyen birine \'Peki neden başaramadınız?\' diye ikinci soruyu yöneltmek hangi mantıksal hatayı içerir?', 'Denediğini söyleyen herkesin başarısız olup hâlâ içtiğini peşinen varsayması', ['Sigara bırakma sürecinin eşit aralıklı ölçekle ölçülemeyeceğini göz ardı etmesi', 'İki sorunun aynı sayfada alt alta yazılmasının görsel uyumu bozması', 'Başarı kavramının yalnızca akademik sınavlar için kullanılabilir bir terim olması'], 'Sigarayı bırakmayı deneyen kişinin ilk denemede başarıp tamamen bırakmış olma ihtimali unutulmuştur; önce şu anki içme durumu sorulmalıdır.'),
  ('\'Ailenizde genetik geçişli nörodejeneratif patoloji öyküsü mevcut mudur?\' sorusu pilot uygulamada katılımcıların %60\'ı tarafından boş bırakılmıştır. İlk yapılması gereken düzeltme nedir?', 'Tıbbi terimleri halkın bildiği \'Alzheimer, Parkinson gibi kalıtsal sinir sistemi hastalıkları\' ifadeleriyle somutlaştırmak', ['Soruyu olduğu gibi koruyup boş bırakmayı engelleyen zorunlu işaretleme kilidi koymak', 'Seçeneklere \'Kesinlikle katılıyorum\' ve \'Kesinlikle katılmıyorum\' basamaklarını eklemek', 'Örneklemdeki tüm katılımcıları tıp fakültesi öğretim üyeleri arasından yeniden seçmek'], 'Yüksek madde yanıtsızlığı burada mahremiyetten değil, ağır tıbbi jargon nedeniyle sorunun anlaşılamamasından (comprehension failure) kaynaklanmaktadır.'),
  ('Bir tutum ölçeğinde \'Sosyal medya gençlerin hem iletişim becerilerini güçlendirir hem de ders başarılarını düşürür\' maddesine \'Katılmıyorum\' diyen birinin gerçek fikri neden bilinemez?', 'İletişimi güçlendirdiğine mi, başarıyı düşürdüğüne mi yoksa ikisine birden mi katılmadığı ayırt edilemediği için', ['Sosyal medya platformlarının adları parantez içinde alfabetik sırayla yazılmadığı için', 'Katılmıyorum seçeneğinin sayısal karşılığı veri tabanında her zaman sıfır olduğu için', 'Genç kavramının alt ve üst yaş sınırları uluslararası hukukta tanımlanmadığı için'], 'Biri olumlu diğeri olumsuz iki ayrı sonucu bağlayan çift namlulu maddelerde alınan tekil puan tamamen yorumlanamaz (uninterpretable) niteliktedir.'),
  ('Bir kamu kurumunun hizmet anketinde \'Personelimiz size her zamanki gibi güler yüzlü ve nazik davrandı mı?\' cümlesi neden kusurludur?', '\'Her zamanki gibi\' ifadesiyle personelin hep nazik olduğunu ön kabul olarak dayatıp yönlendirme yaptığı için', ['Güler yüzlü olmak ile nazik olmak kelimelerinin birbirinin tam zıt anlamlısı olması nedeniyle', 'Kamu kurumlarında vatandaş memnuniyeti ölçülmesinin idare hukukuna aykırı düşmesi yüzünden', 'Cümlede geçmiş zaman kipi kullanıldığı için gelecekteki davranışları kapsam dışı bıraktığından'], '\'Her zamanki gibi\' ön kabulü kurumu peşinen öven yanlı bir çerçeve kurar ve şikâyetçi vatandaşın olumsuz yanıt vermesini psikolojik olarak zorlaştırır.'),
  ('Bir ankette \'Çocuğunuzun ekran süresini kısıtlıyor musunuz?\' sorusundan hemen önce \'Uzmanlar ekran bağımlılığının beyin gelişimine zarar verdiğini kanıtlamıştır\' bilgisinin verilmesi hangi hatadır?', 'Bilgilendirme görünümü altında korku ve normatif baskı yaratan yönlendirici çerçeveleme', ['Filtre sorusuyla çocuksuz bireyleri ilgili bölümden başarıyla ayıklama', 'Sözel sondajlama yoluyla kavramın nasıl anlaşıldığını nitel olarak sınama', 'Eşit aralıklı bir ölçümü oranlı ölçek düzeyine matematiksel olarak taşıma'], 'Tutum veya mevcut davranış ölçülürken hemen öncesinde korkutucu/yönlendirici uzman yargısı paylaşmak mevcut durumu değil telkin etkisini ölçer.'),
  ('\'Haftalık çalışma süreniz kaç saattir?\' sorusuna tam zamanlı çalışanların bir kısmının 40, bir kısmının öğle aralarını da katarak 45, bir kısmının ise yolda geçen süreyi katarak 55 yazması nasıl önlenir?', 'Soru kökünde \'yolda geçen süre ve yemek molaları hariç, fiilî mesai saati\' biçiminde açık operasyonel tanım vererek', ['Açık uçlu sayı kutusunu kaldırıp yerine yalnızca \'Az\' ve \'Çok\' şeklinde iki seçenek koyarak', 'Çalışma saatini çalışanlara sormak yerine tahmini olarak herkese kırk saat atayarak', 'elliden büyük yazılan tüm sayıları veri temizliği sırasında doğrudan sıfıra eşitleyerek'], 'Sınırları muğlak nicel kavramlarda nelerin dahil nelerin hariç olduğunu parantez içinde netleştirmek tüm katılımcıların aynı ölçütü kullanmasını sağlar.'),
  ('Anket tasarımında \'yansıtıcı sorular\' veya \'açıklama sondajları\' olarak kapalı uçlu bir derecelendirmenin hemen altına \'Neden bu puanı verdiğinizi kısaca yazar mısınız?\' eklenmesi ne sağlar?', 'Sayısal puanın arkasındaki somut gerekçeleri anlamayı ve nicel bulguyu nitel bağlamla zenginleştirmeyi', ['Kapalı uçlu sorudan elde edilen sayısal veriyi geçersiz kılarak analizden çıkarmayı', 'Örneklemdeki tüm katılımcıların kapalı uçlu puanlarını orta noktada birleştirmeyi', 'Ölçeğin test-tekrar test güvenirliğini hesaplamaya gerek bırakmadan kanıtlamayı'], 'Karma (hibrit) sıra düzeninde düşük veya yüksek memnuniyet puanının hemen ardından kısa bir açık uçlu \'neden\' sorusu sormak eyleme dönük somut iyileştirme verisi sunar.'),
  ('Çocuklara ve ergenlere yönelik okul anketlerinde öğretmenin sınıf içinde sıraların arasında dolaşarak öğrencilerin kâğıtlarına bakması hangi yanlılığı doğrudan büyütür?', 'Otorite gözetimi nedeniyle kural dışı davranışların gizlenmesi ve sosyal onay yanlılığını', ['Öğrencilerin yaşlarını ve sınıf şubelerini kâğıda daha doğru yazması eğilimini', 'Ölçek maddelerinin kapsam geçerliğinin uzman beklentisine yaklaşması etkisini', 'Tesadüfi ölçme hatalarının birbirini dengeleyerek sıfırlanması sürecini'], 'Okul anketlerinde gizlilik güveni için öğretmen kürsüde/dışarıda durmalı ve tamamlanan formlar öğrencilerin kendisi tarafından mühürlü kutuya atılmalıdır.'),
  ('Anket sorularının yazımında edilgen çatılı ve dolambaçlı cümleler (\'Vergi iadelerinin zamanında yatırılmaması hususunda tarafınızca ne düşünülmektedir?\') yerine neden etken ve doğrudan dil tercih edilmelidir?', 'Bilişsel işlemleme süresini kısaltarak farklı eğitim düzeylerindeki herkesin soruyu tek okuyuşta net anlamasını sağladığı için', ['Etken çatılı cümlelerin resmi yazışma kurallarına göre daha ağır ve bürokratik göründüğü için', 'Edilgen cümlelerin yalnızca telefon anketlerinde kullanılmasına izin verildiği için', 'Doğrudan dil kullanıldığında katılımcıların tüm sorulara \'Katılıyorum\' deme oranı yüzde yüz olduğu için'], 'Bürokratik ve edilgen ifadeler soğukluk ve anlama güçlüğü yaratır; sade, konuşma diline yakın ama özenli etken cümleler (\'Vergi iadelerinin gecikmesi hakkında ne düşünüyorsunuz?\') ölçme hatasını düşürür.'),
  ('Bir anket maddesinde tek bir yanıt seçeneği altında aynı anda iki farklı konunun sorgulanması hangi soru kusuruna örnektir?', 'Çift namlulu soru', ['Örtüşen aralıklı soru', 'Sosyal beğenilirlik sorusu', 'Kapsayıcı olmayan seçenek kusuru'], 'Tek bir maddede iki ayrı yargı veya nesne birleştirildiğinde katılımcı hangisine yanıt vereceğini bilemez; buna çift namlulu (double-barreled) soru denir.'),
  ('"Okul yemekhanesinin yemek kalitesinden ve fiyatlarından memnun musunuz?" sorusundaki temel metodolojik hata nedir?', 'İki ayrı özelliğin tek bir soru kökünde birleştirilmesi', ['Yanıt seçeneklerinin birbirini dışlamaması', 'Katılımcıyı olumlu yanıt vermeye zorlayan sıfat kullanılması', 'Geçmişe dönük uzun süreli bellek yükü oluşturması'], 'Yemek kalitesi ve fiyat birbirinden bağımsız değerlendirilebilecek iki boyuttur; tek soruda sorulması çift namlulu soru kusurudur.'),
  ('Katılımcıyı belirli bir cevabı seçmeye teşvik eden veya duygusal yüklü ifadeler barındıran anket sorularına ne ad verilir?', 'Yönlendirici soru', ['Çift negatifli soru', 'Filtre soru', 'Kontrol sorusu'], 'Sorunun ifade biçimi katılımcıyı belli bir görüşe itiyorsa bu tür maddelere yönlendirici (leading) veya yüklü soru denir.'),
  ('Bir yaş sorusunda seçeneklerin "18-25", "25-35", "35-45" şeklinde verilmesi hangi teknik kusuru oluşturur?', 'Örtüşen aralıklar', ['Eksik kapsayıcılık', 'Çift namlulu kök', 'Tavan etkisi'], '25 ve 35 yaşındaki katılımcılar iki farklı seçeneğe de girebildiği için seçenekler birbirini dışlamaz ve örtüşen aralık kusuru doğar.'),
  ('Katılımcıların gerçek düşünceleri yerine toplum tarafından hoş karşılanacak veya takdir edilecek yanıtlar verme eğilimine ne denir?', 'Sosyal beğenilirlik yanlılığı', ['Hatırlama yanlılığı', 'Onaylama yanlılığı', 'Hayatta kalma yanlılığı'], 'Bireylerin kendilerini olduğundan daha iyi, ahlaklı veya uyumlu gösterme çabası sosyal beğenilirlik (social desirability) yanlılığıdır.'),
  ('Geçmişteki olayların, deneyimlerin veya sıklıkların katılımcılar tarafından eksik ya da hatalı anımsanmasından kaynaklanan sistematik hataya ne ad verilir?', 'Hatırlama yanlılığı', ['Seçim yanlılığı', 'Yayın yanlılığı', 'Gözlemci yanlılığı'], 'Geçmişe dönük (retrospektif) veri toplarken belleğin yanılması veya seçici çalışması hatırlama (recall) yanlılığı olarak adlandırılır.'),
  ('"Sorumsuz sürücülerin neden olduğu trafik kazalarını önlemek için cezalar artırılmalı mıdır?" sorusundaki kusur türü nedir?', 'Yüklü ve yönlendirici ifade kullanımı', ['Çift negatifli dil bilgisi yapısı', 'Birbirini dışlamayan seçenek aralıkları', 'Yetersiz bellek ipucu verilmesi'], '"Sorumsuz sürücüler" gibi duygusal açıdan yüklü bir niteleme katılımcıyı cezaların artırılması yönünde oy vermeye iter.'),
  ('Katılımcının soru içeriğinden bağımsız olarak anketteki maddelere sürekli "Katılıyorum" veya "Evet" deme eğilimine ne ad verilir?', 'Onaylama (evet deme) yanlılığı', ['Hatırlama yanlılığı', 'Yıpranma yanlılığı', 'Seçici algı yanlılığı'], 'İçeriğe dikkat etmeksizin olumlu seçenekleri işaretleme alışkanlığı onaylama (acquiescence / yea-saying) yanlılığıdır.'),
  ('Çok dereceli (örneğin 5\'li Likert) ölçeklerde katılımcıların uç seçeneklerden kaçınıp sürekli "Kararsızım / Orta" seçeneğine yönelmesine ne denir?', 'Merkezi eğilim yanlılığı', ['Sosyal beğenilirlik yanlılığı', 'Teleskoplama yanlılığı', 'Uç değer yanlılığı'], 'Karar vermekten kaçınma veya çekingenlik nedeniyle orta noktanın aşırı tercih edilmesi merkezi eğilim (central tendency) yanlılığıdır.'),
  ('"Haftada düzenli olarak spor yapar mısınız?" sorusundaki "düzenli" kelimesi hangi soru kusuruna yol açar?', 'Muğlak (belirsiz) ifade kusuru', ['Örtüşen aralık kusuru', 'Çift negatif kusuru', 'Sosyal kimlik ifşası'], '"Düzenli", "sık sık", "bazen" gibi göreli zarflar her katılımcı için farklı bir sıklık (kimine göre haftada 1, kimine göre her gün) ifade ettiğinden muğlaktır.'),
  ('"Belediyenin yeni yaptığı görkemli kültür merkezini beğendiniz mi?" sorusunda hangi kelime soruyu yönlendirici hale getirmektedir?', 'Görkemli', ['Belediyenin', 'Kültür', 'Yeni'], '"Görkemli" sıfatı nesneye baştan olumlu bir değer yükleyerek katılımcıyı "Beğendim" demeye yönlendirir.'),
  ('Kapalı uçlu bir anket sorusunda sunulan seçeneklerin hiçbir katılımcıyı açıkta bırakmayacak biçimde tüm olası durumları içermesi özelliğine ne denir?', 'Kapsayıcılık', ['Karşılıklı dışlayıcılık', 'Çift namluluk', 'Tek boyutluluk'], 'Seçenek kümesinin olası bütün cevapları barındırması kapsayıcılık (exhaustiveness); seçeneklerin birbiriyle çakışmaması ise karşılıklı dışlayıcılıktır.'),
  ('Kapalı uçlu bir soruda bir katılımcının aynı anda birden fazla seçeneğin kapsamına girmemesi, yani aralıkların çakışmaması ilkesine ne ad verilir?', 'Karşılıklı dışlayıcılık', ['Sosyal beğenilirlik', 'Geçmişe dönük hatırlama', 'İç tutarlılık'], 'Örtüşen aralık kusurunun bulunmaması, her bir değerin yalnızca tek bir seçeneğe karşılık gelmesi karşılıklı dışlayıcılık (mutual exclusiveness) ilkesidir.'),
  ('"Okul kantininde sağlıklı gıdaların satılmamasına karşı değil misiniz?" sorusu nasıl sadeleştirilmelidir?', 'Okul kantininde sağlıklı gıdaların satılmasını destekliyor musunuz?', ['Okul kantininde sağlıklı gıdaların ve kırtasiye ürünlerinin satılmasını ister misiniz?', 'Uzmanların önerdiği gibi kantinde sağlıklı gıdaların satılması gerekmez mi?', 'Okul kantininde sağlıksız gıdaların yasaklanmamasına itirazınız yok mu?'], 'Çift/üçlü olumsuzluk ("satılmamasına", "karşı", "değil") tamamen kaldırılıp net, olumlu ve tek boyutlu bir soru köküne dönüştürülmelidir.'),
  ('Anket maddelerinde "Hiç katılmıyorum"dan "Tamamen katılıyorum"a uzanan dereceli tepki kategorilerinin olumlu ve olumsuz uçlarda eşit sayıda olmasına ne denir?', 'Dengeli ölçek yapısı', ['Örtüşen ölçek yapısı', 'Çift namlulu ölçek yapısı', 'Rastgeleleştirilmiş ölçek yapısı'], 'Örneğin iki olumsuz ("Hiç katılmıyorum", "Katılmıyorum") ve iki olumlu ("Katılıyorum", "Tamamen katılıyorum") seçenek içeren simetrik yapı dengeli (balanced) ölçektir.'),
  ('"Aşağıdaki dergilerden hangisini okursunuz? A) Bilim ve Teknik B) Atlas C) Hiçbiri" sorusunda hem Bilim ve Teknik hem Atlas okuyan bir katılımcı tek seçenek işaretleyebiliyorsa hangi sorun yaşanır?', 'Tek yanıt zorunluluğunun gerçek durumu yansıtmaması', ['Sorunun katılımcıyı dergi okumaya zorlayan yönlendirici sıfatlar içermesi', 'Soru kökünde çift negatifli dil bilgisi kurgusunun kullanılması', 'Katılımcının çocukluk yıllarına ilişkin hatırlama yanlılığı yaşaması'], 'Birden fazla seçeneğin aynı anda doğru olabileceği davranışlarda tek seçime zorlamak ("En çok hangisini..." demeden) yanıtlayıcıyı sıkıştırır ve veri kaybına neden olur.'),
  ('Anket formunun gerçek örneklem üzerinde uygulanmadan önce küçük ama benzer bir grupta anlaşılırlık ve soru kusurları açısından denenmesine ne ad verilir?', 'Pilot uygulama', ['Meta-analiz', 'Boylamasına izlem', 'Çift körleme'], 'Sorulardaki muğlak ifadeleri, örtüşen aralıkları veya çift namlulu maddeleri saha öncesinde yakalamanın en temel yolu pilot uygulamadır.'),
  ('"Kitap okumak gibi faydalı bir alışkanlığa günde kaç dakika ayırırsınız?" sorusu katılımcıda hangi iki etkiyi aynı anda tetikleyebilir?', 'Yönlendirici ifade etkisi ve sosyal beğenilirlik yanlılığı', ['Çift negatif kafa karışıklığı ve örtüşen aralık hatası', 'Sonralık etkisi ve yıpranma yanlılığı', 'Taban etkisi ve gözlemci körlüğü'], '"Faydalı bir alışkanlık" nitelemesi yönlendiricidir; aynı zamanda toplumsal olarak makbul bir davranışı vurguladığı için katılımcının süreyi olduğundan fazla bildirmesine (sosyal beğenilirlik) yol açar.'),
  ('"Yeni vergi düzenlemesini adil ve anlaşılır buluyor musunuz?" sorusu neden çift namlulu bir sorudur?', 'Bir düzenleme adil bulunurken karmaşık bulunabileceği (veya anlaşılır olup adaletsiz bulunabileceği) için', ['Vergi kelimesinin halk arasında duygusal korku uyandıran teknik bir terim olması nedeniyle', 'Sorunun katılımcıdan son on yıldaki ödediği tüm vergileri hatırlamasını istemesi yüzünden', 'Yanıt seçeneklerinin birden fazla kutucuğu işaretlemeye izin vermemesi sebebiyle'], '"Adil olma" ve "anlaşılır olma" birbirinden bağımsız iki niteliktir; tek soruda birleştirilmeleri çift namlulu kusurdur.'),
  ('Bir anket maddesinde hem kökün hem de yanıt seçeneğinin olumsuz ifade içermesiyle anlamın tersine dönmesi durumuna ne ad verilir?', 'Çift olumsuzlama (çift negatif) kusuru', ['Örtüşen kategori kusuru', 'Hale etkisi kusuru', 'Tavan etkisi kusuru'], 'Örneğin "Katضور zorunluluğunun kaldırılmamasına" köküne "Katılmıyorum" yanıtı verildiğinde kimin neyi savunduğunu çözmek zorlaşır; bu çift negatif kusurudur.'),
  ('Katılımcının yaşını öğrenmek isteyen bir araştırmacı, örtüşen aralık veya eksik kapsayıcılık riskine hiç girmemek için soruyu en temiz nasıl sorabilir?', '"Doğum yılınız nedir? (____)" veya "Kaç yaşındasınız? (____)" şeklinde açık uçlu sayısal giriş isteyerek', ['"Yaşınız hangi aralıktadır? A) Genç B) Orta yaşlı C) Yaşlı" şeklinde sorarak', '"Yaşınız ve eğitim süreniz toplam kaç yıldır?" biçiminde tek soruda birleştirerek', '"18-30", "30-50", "50-65" seçeneklerinden birini zorunlu tutarak'], 'Sürekli/oran ölçeğindeki bir değişkeni (yaş, doğum yılı) doğrudan sayı olarak alıp gerekirse analiz aşamasında gruplandırmak hem örtüşme hatasını önler hem de bilgi kaybını engeller.'),
  ('Katılımcıların "Bilmiyorum" veya "Fikrim yok" seçeneği sunulmadığında hakkında hiçbir bilgi sahibi olmadıkları konularda bile rastgele bir tutum bildiriyormuş gibi görünmesine ne ad verilir?', 'Sözde tutum', ['Hatırlama yanlılığı', 'Örtüşen kategori hatası', 'Yıpranma etkisi'], 'Bilgi sahibi olunmayan konularda "Fikrim yok / Bilmiyorum" filtresi konulmazsa katılımcılar bilgisiz görünmemek için rastgele seçenek işaretleyerek sözde tutum üretir.'),
  ('"Okul yönetiminin adil, şeffaf ve öğrenci odaklı kararlarını destekliyor musunuz?" sorusu neden bilimsel bir anket maddesi olamaz?', 'Kararların adil, şeffaf ve öğrenci odaklı olduğunu peşinen kabul ettiren aşırı yönlendirici ve çok boyutlu bir kök içerdiği için', ['Sorunun sonunda soru işareti yerine ünlem işareti kullanılması gerektiği için', 'Katılımcının geçmişteki tüm okul müdürlerini sırasıyla hatırlamasını istediği için', 'Yanıt seçeneklerinde sayısal değerler yerine harf kodları kullanıldığı için'], 'Hem güçlü olumlu sıfatlarla yönlendirme yapmakta hem de üç ayrı niteliği (adil, şeffaf, öğrenci odaklı) tek maddede birleştirmektedir.'),
  ('Bir araştırmada anket sorularının açık, net, tek anlamlı olması ve her katılımcı tarafından aynı biçimde yorumlanması hangi temel ilkeyi ifade eder?', 'Soru anlaşılırlığı ve standart anlamlılık', ['Rastgeleleştirilmiş yanıtlama', 'Teleskoplama düzeltmesi', 'Çoklu olumsuzlama'], 'Ölçmede standardizasyonun ilk şartı, uyaranın (sorunun) tüm katılımcılar için aynı anlamı taşımasıdır.'),
  ('Bir ölçme aracının tesadüfi (rastgele) ölçme hatalarından arınık olma ve tutarlı sonuçlar üretme derecesine ne ad verilir?', 'Güvenirlik', ['Görünüş geçerliği', 'Kapsam geçerliği', 'Sosyal beğenilirlik'], 'Güvenirlik (reliability), ölçme sonuçlarının rastgele hatalardan ne ölçüde arınık olduğunu, yani ölçümün kararlılığını ve tutarlılığını gösterir.'),
  ('Çok maddeli Likert tipi bir ölçeğin maddelerinin birbiriyle ne ölçüde uyumlu olduğunu (iç tutarlılığını) belirlemek için en yaygın kullanılan katsayı hangisidir?', 'Cronbach alfa katsayısı', ['Cohen kappa katsayısı', 'Pearson çarpım momentler farkı', 'Ki-kare bağımsızlık katsayısı'], 'Derecelendirmeli (politomik) ölçeklerde maddelerin kendi aralarındaki iç tutarlılığını hesaplamada standart yöntem Cronbach alfa katsayısıdır.'),
  ('İki bağımsız uzman veya hakemin kategorik (sınıflamalı) bir değerlendirmedeki şans etkisinden arındırılmış uyum derecesini ölçen istatistik hangisidir?', 'Cohen kappa katsayısı', ['Cronbach alfa katsayısı', 'KR-20 katsayısı', 'Madde güçlük indeksi'], 'İki puanlayıcının kategorik kararlarında tesadüfi uyumu düşerek gerçek uzlaşmayı hesaplayan katsayı Cohen kappa (κ) katsayısıdır.'),
  ('Bir ölçme aracının ölçmeyi amaçladığı özelliği, başka özelliklerle karıştırmadan doğru ve tam olarak ölçebilme derecesine ne ad verilir?', 'Geçerlik', ['İç tutarlılık', 'Yarıya bölme kararlılığı', 'Puanlayıcılar arası uyum'], 'Geçerlik (validity), aracın "neyi" ne kadar isabetli ve amaca uygun ölçtüğüyle, yani hem sistematik hem tesadüfi hatalardan arınıklıkla ilgilidir.'),
  ('Bir testteki maddelerin ölçülmek istenen konu alanını (evrenini) dengeli ve eksiksiz biçimde temsil edip etmediğini uzman görüşleriyle inceleyen geçerlik türü hangisidir?', 'Kapsam (içerik) geçerliği', ['Yordama geçerliği', 'Eş zamanlı ölçüt geçerliği', 'Görünüş geçerliği'], 'Maddelerin hedef davranış veya konu evrenini yeterince örnekleyip örneklemediği kapsam (content) geçerliği ile değerlendirilir.'),
  ('Soyut psikolojik kavramların (zeka, kaygı, motivasyon vb.) kuramsal beklentilere uygun biçimde ölçülüp ölçülmediğini faktör analizi ve hipotez testleriyle inceleyen en kapsamlı geçerlik türü hangisidir?', 'Yapı geçerliği', ['Görünüş geçerliği', 'Paralel formlar güvenirliği', 'Yarıya bölme güvenirliği'], 'Soyut bir yapının (construct) kuramsal boyutlarını ve diğer yapılarla ilişkilerini doğrulama süreci yapı geçerliğidir.'),
  ('Bir ölçek veya sınav çok kolay olduğunda katılımcıların büyük çoğunluğunun alınabilecek en yüksek puana (veya çok yakınına) yığılması durumuna ne ad verilir?', 'Tavan etkisi (ceiling effect)', ['Taban etkisi (floor effect)', 'Hale etkisi (halo effect)', 'Teleskoplama etkisi'], 'Puanların üst sınırda kümelenmesi nedeniyle üst düzeydeki başarılı/yüksek özellikli bireylerin birbirinden ayırt edilememesi tavan etkisidir.'),
  ('Bir ölçek veya test hedef gruba göre aşırı zor olduğunda katılımcıların büyük kısmının en düşük olası puanda toplanması durumuna ne denir?', 'Taban etkisi (floor effect)', ['Tavan etkisi (ceiling effect)', 'Sosyal beğenilirlik etkisi', 'Öncelik etkisi'], 'Puanların alt sınırda (sıfır veya minimum ölçek puanında) yığılması ve alt düzeydeki bireylerin kendi aralarında ayrıştırılamaması taban etkisidir.'),
  ('Bir maddenin ölçülen özelliğe yüksek düzeyde sahip olan bireylerle düşük düzeyde sahip olan bireyleri birbirinden ayırma gücüne ne ad verilir?', 'Madde ayırt edicilik indeksi', ['Madde güçlük indeksi', 'Standart ölçme hatası', 'Kapsam geçerlik oranı'], 'İyi bir ölçek veya test maddesi, toplam puanda üst grupta yer alanlarla alt grupta yer alanları net biçimde ayrıştırmalıdır; buna madde ayırt ediciliği denir.'),
  ('Klasik madde analizinde madde ayırt edicilik indeksi (veya düzeltilmiş madde-toplam korelasyonu) kaçın altında kalan maddelerin genellikle ölçekten çıkarılması ya da düzeltilmesi önerilir?', '0,20\'nin altında kalan', ['0,80\'in altında kalan', '0,90\'ın altında kalan', '0,75\'in altında kalan'], 'Genel kural olarak 0,19 ve altı çok zayıf (çıkarılmalı), 0,20-0,29 düzeltilmeli, 0,30-0,39 iyi, 0,40 ve üzeri çok iyi ayırt edici kabul edilir.'),
  ('İkili puanlanan (Doğru=1, Yanlış=0) başarı veya bilgi testlerinde iç tutarlılık güvenirliğini hesaplamak için Cronbach alfa\'nın özel hali olarak kullanılan yöntem hangisidir?', 'Kuder-Richardson 20', ['Cohen kappa', 'Lawshe kapsam geçerlik oranı', 'Ağırlıklı kappa'], 'Maddelerin 1-0 şeklinde dikotom puanlandığı ve madde güçlüklerinin farklı olabildiği testlerde iç tutarlılık KR-20 formülüyle hesaplanır (alfa katsayısı 1-0 veride KR-20 ile birebir aynı sonucu verir).'),
  ('Yeni geliştirilen bir ölçekte maddelerin kaç alt boyut (faktör) altında toplandığını önceden kesin bir model dayatmadan veri üzerinden keşfetmek için kullanılan istatistiksel yöntem hangisidir?', 'Açımlayıcı Faktör Analizi (AFA / EFA)', ['Doğrulayıcı Faktör Analizi (DFA / CFA)', 'Tek yönlü varyans analizi (ANOVA)', 'Bağımsız gruplar t-testi'], 'Verideki gizil (latent) yapıyı ve maddelerin hangi boyutlarda kümelendiğini keşfetmek amacıyla Açımlayıcı Faktör Analizi kullanılır.'),
  ('3 maddelik çok kısa bir alt ölçek ile 25 maddelik uzun bir ölçeğin maddeler arası ortalama korelasyonu eşit (örneğin r̄ = 0,30) olsa bile hangisinin Cronbach alfa katsayısı daha yüksek çıkar?', 'Madde sayısı fazla olduğu için 25 maddelik ölçeğin Cronbach alfa katsayısı daha yüksek çıkar', ['Madde sayısı az olduğu için 3 maddelik alt ölçeğin Cronbach alfa katsayısı daha yüksek çıkar', 'Ortalama korelasyon eşit olduğundan her iki ölçeğin Cronbach alfa değeri virgülden sonra bile birebir aynı çıkar', '3 maddelik ölçeğin Cronbach alfası her zaman negatif çıkar'], 'Cronbach alfa formülü madde sayısına (k) duyarlıdır: α = (k × r̄) / [1 + (k - 1) × r̄]. Ortalama madde korelasyonu sabitken k arttıkça alfa büyür (k=3 için ~0,56; k=25 için ~0,91).'),
  ('Açık uçlu yazılı sınavların veya performans ödevlerinin puanlanmasında puanlayıcı öznelliğinden kaynaklanan hatayı kontrol etmek için en uygun güvenirlik yaklaşımı hangisidir?', 'Ayrıntılı dereceli puanlama anahtarı (rubrik) kullanarak bağımsız puanlayıcılar arası uyumu hesaplamak', ['Sınavdaki tek ve çift numaralı soruların aritmetik ortalamalarını toplamak', 'Öğrencilere sınavdan 1 yıl sonra aynı soruları tekrar sormak', 'Soruların yalnızca görünüş geçerliğini incelemek'], 'Açık uçlu veya performansa dayalı ölçümlerde hata kaynağının önemli bir kısmı puanlayıcı öznelliğidir; standart rubrik ve puanlayıcılar arası güvenirlik (kappa veya sınıf içi korelasyon - ICC) esastır.'),
  ('Bir matematik sınavında geometri, cebir ve olasılık üniteleri ders saatlerinde eşit ağırlıkta işlenmiş olmasına rağmen sınavdaki 30 sorunun 28\'i yalnızca cebirden sorulmuşsa hangi geçerlik türü doğrudan zedelenmiştir?', 'Kapsam geçerliği', ['Yordama geçerliği', 'Puanlayıcılar arası güvenirlik', 'İç tutarlılık güvenirliği'], 'Hedeflenen müfredat evrenindeki alt konuların sınavda orantılı temsil edilmemesi doğrudan kapsam (içerik) geçerliğini bozar; cebir soruları kendi içinde tutarlı olacağı için alfa yüksek kalabilir!'),
  ('Bir testteki tüm maddelerin tek bir baskın gizil özelliği (örneğin yalnızca okuma kaygısını) ölçmesi ve başka ikincil boyutların puanları karıştırmaması özelliğine ne denir?', 'Tek boyutluluk', ['Çoklu doğrusallık', 'Çift namluluk', 'Puanlayıcı öznelliği'], 'Tek bir toplam puan üretilen ölçek veya alt ölçeklerde tüm maddelerin aynı temel yapıyı ölçmesi tek boyutluluk ilkesidir.'),
  ('Çoktan seçmeli bir test maddesinde doğru cevabı bilmeyen alt gruptaki öğrencilerin hiçbirinin işaretlemediği (0 kişinin seçtiği) bir yanlış seçenek (çeldirici) için ne söylenebilir?', 'Çeldirici işlevini yerine getirememektedir; soru fiilen daha az seçenekli hale gelmiş ve şans başarısı artmıştır', ['Çeldirici mükemmel çalışmıştır; bilen ile bilmeyeni en yüksek düzeyde ayırt etmiştir', 'Bu seçenek sorunun kapsam geçerliğini tek başına iki katına çıkarmıştır', 'Bu seçenek nedeniyle testin tamamında taban etkisi oluşmuştur'], 'İyi bir çeldiricinin alt gruptaki (bilmeyen) öğrencileri kendine çekmesi ve üst gruptan daha fazla alt grup tarafından seçilmesi beklenir; hiç seçilmeyen çeldirici ölü seçenektir, değiştirilmelidir.'),
  ('Ölçek geliştirme sürecinde faktör analizi sonucunda bir faktörün açıkladığı varyans büyüklüğünü gösteren ve klasik Kaiser ölçütüne göre 1,00\'den büyük olması beklenen istatistiğe ne ad verilir?', 'Özdeğer', ['Standart hata', 'Kappa katsayısı', 'Güçlük indeksi'], 'Kaiser kriterine göre özdeğeri (eigenvalue) 1\'in üzerinde olan bileşenler/faktörler anlamlı aday sayılır; ancak güncel uygulamada yamaç birikinti grafiği (scree plot) ve paralel analizle birlikte değerlendirilir.'),
  ('Bir ölçme aracındaki maddelerin yazım hatalarından arındırılması, yönergelerin netleştirilmesi ve puanlama anahtarının standartlaştırılması doğrudan neyi azaltır?', 'Tesadüfi (rastgele) ölçme hatasını azaltarak güvenirliği artırır', ['Örneklem büyüklüğünü azaltarak maliyeti düşürür', 'Madde ayırt edicilik indeksini sıfıra indirir', 'Faktör sayısını iki katına çıkarır'], 'Belirsiz yönergeler ve dizgi hataları katılımcıların rastgele yanılmasına (tesadüfi hata) yol açar; bunların giderilmesi doğrudan güvenirliği ve dolaylı olarak geçerliği yükseltir.'),
];
